(r/"test/zach-edit-access.test.mjs").write_text("import test from 'node:test';\nimport assert from 'node:assert/strict';\nimport {mkdtempSync,rmSync} from 'node:fs';\nimport {tmpdir} from 'node:os';\nimport path from 'node:path';\nimport {randomBytes,randomUUID,createHmac} from 'node:crypto';\nimport {createApplication} from '../server/index.mjs';\nimport {hash} from '../server/security.mjs';\nimport {execute,initialState,engine} from '../server/engine.mjs';\ntest('Zach private link edits another marketer lead, attributes changes, protects owner tools, and revokes immediately',async()=>{\n const dir=mkdtempSync(path.join(tmpdir(),'zach-editor-')),access=randomBytes(32).toString('hex'),secret='zach-editor-test';\n const env={NODE_ENV:'test',APP_MODE:'live',PHI_APPROVED:'true',SQLITE_PATH:path.join(dir,'state.sqlite'),SESSION_SECRET:secret,VIEWER_ACCESS_HASH:hash(access),VIEWER_ACCESS_EXPIRES_AT:'never',VIEWER_EMAIL:'zach@tharongroup.com',ZACH_LEAD_EDIT_ACCESS:'true'};\n const app=await createApplication({env,schedule:false});await new Promise(r=>app.server.listen(0,'127.0.0.1',r));const origin='http://127.0.0.1:'+app.server.address().port;\n try{\n const fake=execute(initialState(false),'u0',{op:'createLead',createdId:'L_zach_example',args:[{first:'Fictional',last:'Editor',building:'hallmark',rep:'u3',payer:'Private pay'}]});await app.store.query('UPDATE app_state SET data=$1 WHERE id=$2',[JSON.stringify(fake),'main']);\n const login=()=>fetch(origin+'/auth/viewer-access',{method:'POST',headers:{Origin:origin,'Content-Type':'application/json'},body:JSON.stringify({token:access})});\n const r=await login();assert.equal(r.status,200);const cookie=r.headers.get('set-cookie').split(';')[0],headers={Cookie:cookie,Origin:origin};\n const boot=await(await fetch(origin+'/api/state',{headers})).json();assert.equal(boot.state.me,'u6');assert.equal(engine(boot.state,'u6').me().email,'zach@tharongroup.com');assert.ok(!engine(boot.state,'u6').referralStaff().some(u=>u.id==='u6'));\n assert.equal((await fetch(origin+'/viewer',{headers,redirect:'manual'})).headers.get('location'),'/');assert.equal((await fetch(origin+'/',{headers})).status,200);\n const cmd={id:randomUUID(),op:'updateLead',expectedVersion:1,args:['L_zach_example',{notes:'Edited by Zach'}]};\n const send=csrf=>fetch(origin+'/api/commands',{method:'POST',headers:{...headers,'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify(cmd)});\n assert.equal((await send('wrong')).status,403);assert.equal((await send(boot.csrf)).status,200);\n const fresh=await(await fetch(origin+'/api/state',{headers})).json();assert.equal(fresh.state.leads[0].notes,'Edited by Zach');assert.equal(fresh.state.leads[0].rep,'u3');assert.equal((await app.store.query('SELECT user_id FROM audit_log WHERE action=$1',['updateLead']))[0].user_id,'u6');\n for(const endpoint of ['/api/admin/activity','/api/users','/api/admin/viewer-access','/api/admin/personal-access'])assert.equal((await fetch(origin+endpoint,{headers})).status,403,endpoint);\n for(const op of ['settings','setBuildingAccess'])assert.throws(()=>execute(fresh.state,'u6',{op,args:[]}),/account administration/);\n const token='owner-zach-revoke';await app.store.query('INSERT INTO sessions (token_hash,user_id,expires_at,csrf) VALUES ($1,$2,$3,$4)',[createHmac('sha256',secret).update(token).digest('hex'),'u0',Date.now()+60000,'owner-csrf']);\n assert.equal((await fetch(origin+'/api/admin/viewer-access',{method:'DELETE',headers:{Cookie:'tl_session='+token,Origin:origin,'X-CSRF-Token':'owner-csrf'}})).status,200);\n assert.equal((await fetch(origin+'/api/state',{headers})).status,401);assert.equal((await login()).status,403);\n }finally{await app.close();rmSync(dir,{recursive:true,force:true});}\n});\ntest('edit access requires explicit activation and exact Zach email; generic viewers stay read-only',async()=>{\n for(const extra of [{VIEWER_EMAIL:'other@example.com',ZACH_LEAD_EDIT_ACCESS:'true'},{VIEWER_EMAIL:'zach@tharongroup.com'}]){\n const dir=mkdtempSync(path.join(tmpdir(),'zach-gating-')),access=randomBytes(32).toString('hex');const app=await createApplication({env:{NODE_ENV:'test',APP_MODE:'live',PHI_APPROVED:'true',SQLITE_PATH:path.join(dir,'state.sqlite'),VIEWER_ACCESS_HASH:hash(access),VIEWER_ACCESS_EXPIRES_AT:'never',...extra},schedule:false});await new Promise(r=>app.server.listen(0,'127.0.0.1',r));const origin='http://127.0.0.1:'+app.server.address().port;\n try{const login=await fetch(origin+'/auth/viewer-access',{method:'POST',headers:{Origin:origin,'Content-Type':'application/json'},body:JSON.stringify({token:access})});const cookie=login.headers.get('set-cookie').split(';')[0],boot=await(await fetch(origin+'/api/state',{headers:{Cookie:cookie}})).json();assert.equal(boot.state.me,'u5');assert.throws(()=>execute(boot.state,'u5',{op:'updateLead',args:[]}),/View-only/);}finally{await app.close();rmSync(dir,{recursive:true,force:true});}\n }\n});\n")

